struct RClass*
get_real_class(struct RClass* cl) {
  if (!cl) {
    return NULL;
  }

  while (cl) {
    if (!(RCLASS_CLS_FLAGS(cl) & RCLASS_CLS_FLAG_SINGLETON) &&
        !(RCLASS_CLS_FLAGS(cl) & RCLASS_CLS_FLAG_INCLUDED)) {
      return cl;
    }
    cl = RCLASS_SUPER(cl);
  }

  return NULL;
}

struct RClass* get_real_class(struct RClass* cl) {
  if (cl == NULL) {
    return NULL;
  }

  struct RClass* current_class = cl;
  while (current_class != NULL) {
    if (!(CLASS_ANY(current_class)) &&
        !(CLASS_SINGLETON(current_class))) {
      return current_class;
    }
    current_class = current_class->super;
  }

  return NULL;
}

