struct RClass*
get_real_class(struct RClass* cl) {
  if (cl == NULL) {
    return NULL;
  }

  while (cl != NULL) {
    if (!RCLASS_FLAG_CLONE(cl) && !RCLASS_FLAG_INCLUD(cl)) {
      return cl;
    }
    cl = RCLASS_SUPER(cl);
  }

  return NULL;
