struct RClass* get_real_class(struct RClass* cl) {
    if (cl == NULL) {
        return NULL;
    }

    while (1) {
        // Check if current class is a singleton or included class
        if (cl->super == NULL) {
            return cl;
        }

        cl = cl->super;
    }
}
